set -eu; out=$1; pro=$2; gui=$(command -v kicad || true); for g in "$gui" /usr/bin/kicad /Applications/KiCad/KiCad.app/Contents/MacOS/kicad; do [ -n "$g" ] && [ -x "$g" ] || continue; c=$(dirname "$g")/kicad-cli; [ -x "$c" ] || continue; v=$("$c" version 2>/dev/null) || continue; case "$v" in 10.0.[0-9]*) ;; *) continue;; esac; case "$v" in *bp.*) continue;; esac; if [ "$(uname)" = Darwin ]; then open -a /Applications/KiCad/KiCad.app "$pro"; else setsid -f "$g" "$pro" </dev/null >/dev/null 2>&1; fi; exit 0; done; set -- "$out"; p="$1"; case "$p" in "~/"*) p="$HOME/${p#??}";; esac; case "$p" in /*) ;; *) p="$PWD/$p";; esac; [ -e "$p" ] || { echo "No such file: $p"; exit 1; }; if [ "$(uname)" = Darwin ]; then open "$p"; exit $?; fi; [ -n "$DISPLAY$WAYLAND_DISPLAY" ] || { echo "No desktop on this machine to open it on"; exit 1; }; (${BACKPLANE_OPEN:-xdg-open} "$p" >/dev/null 2>&1 &)